(() => {
  const state = {
    themeSettings: null,
    cartUrl: null,
  };

  let cachedCart = null;
  let cartRequest = null;
  let cachedCollectionProducts = {}; // Cache for collection product IDs

  const requireConfig = () => {
    if (!state.themeSettings) {
      throw new Error('[FreeProduct] configure({ themeSettings, cartUrl }) must run before using helpers.');
    }
    return state.themeSettings;
  };

  const getCartUrl = () => state.cartUrl ?? '/cart';

  const setCachedCart = (cart) => {
    cachedCart = cart ?? null;
  };

  const invalidateCart = () => {
    cachedCart = null;
    cartRequest = null;
  };

  const fetchCart = async () => {
    if (cachedCart) {
      return cachedCart;
    }

    if (!cartRequest) {
      cartRequest = fetch('/cart.js', {
        credentials: 'same-origin',
        headers: {
          Accept: 'application/json',
        },
      })
        .then((response) => {
          if (!response.ok) {
            throw new Error('Error fetching cart: ' + response.statusText);
          }
          return response.json();
        })
        .then((cart) => {
          setCachedCart(cart);
          return cart;
        })
        .catch((error) => {
          cartRequest = null;
          throw error;
        });
    }

    return cartRequest;
  };

  const resolveCart = async (cartContent) => {
    if (cartContent) {
      setCachedCart(cartContent);
      return cartContent;
    }
    return fetchCart();
  };

  /**
   * Fetch product IDs from a collection
   * @param {string} collectionHandle - The collection handle
   * @returns {Promise<number[]>} Array of product IDs in the collection
   */
  const getCollectionProductIds = async (collectionHandle) => {
    if (!collectionHandle) return null;

    // Return cached result if available
    if (cachedCollectionProducts[collectionHandle]) {
      return cachedCollectionProducts[collectionHandle];
    }

    try {
      const response = await fetch(`/collections/${collectionHandle}/products.json?limit=250`, {
        credentials: 'same-origin',
        headers: {
          Accept: 'application/json',
        },
      });

      if (!response.ok) {
        console.warn(`[FreeProduct] Could not fetch collection ${collectionHandle}`);
        return null;
      }

      const data = await response.json();
      const productIds = data.products.map((product) => product.id);

      // Cache the result
      cachedCollectionProducts[collectionHandle] = productIds;

      return productIds;
    } catch (error) {
      console.error('[FreeProduct] Error fetching collection products:', error);
      return null;
    }
  };

  const checkGiftInCart = (cartContent, giftProducts) => {
    const products = giftProducts ?? requireConfig()['free-products__condition_products'];
    const cartVariantIds = cartContent.items.map((item) => item.variant_id);
    return products.some((gift) => cartVariantIds.includes(gift.variants[0].id));
  };

  const refreshCart = () => {
    const cartUrl = getCartUrl();
    if (window.location.pathname === cartUrl) {
      window.location.href = cartUrl;
    } else {
      document.documentElement.dispatchEvent(
        new CustomEvent('cart:refresh', {
          bubbles: true,
        }),
      );
    }
  };

  const removeAllGiftedItems = async ({ refreshOnNoMatch = false } = {}) => {
    try {
      const cartContent = await fetchCart();
      const giftedItems = cartContent.items.filter(
        (item) => item.properties && item.properties._Gifted === true && item.properties._autoAdded === true,
      );

      if (giftedItems.length === 0) {
        return { needsRefresh: refreshOnNoMatch, removed: 0 };
      }

      let data = null;

      for (const item of giftedItems) {
        const response = await fetch('/cart/change.js', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            id: String(item.id),
            quantity: 0,
          }),
        });

        if (!response.ok) {
          throw new Error('Error removing gifted product from cart: ' + response.statusText);
        }

        data = await response.json();
        setCachedCart(data);
      }

      return { needsRefresh: true, data, removed: giftedItems.length };
    } catch (error) {
      console.error('[FreeProduct] Error removing gifted items:', error);
      throw error;
    }
  };

  const addToCart = async () => {
    try {
      const settings = requireConfig();
      const items = settings['free-products__condition_products'].map((prod) => ({
        quantity: 1,
        id: prod.variants[0].id,
        properties: {
          _autoAdded: true,
          _condition: settings['free-products__condition_type'],
          _Gifted: true,
        },
      }));

      const response = await fetch('/cart/add.js', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ items }),
      });

      if (!response.ok) {
        throw new Error('Error adding product to cart: ' + response.statusText);
      }

      const data = await response.json();
      // /cart/add.js restituisce solo gli items aggiunti, non il carrello completo
      // Invalidiamo la cache per forzare un fetch fresco
      invalidateCart();

      return { needsRefresh: true, data };
    } catch (error) {
      console.error('[FreeProduct] Error adding gift products:', error);
      throw error;
    }
  };

  const checkGiftCondition = async (cartContent, { refreshOnNoChange = false, refreshOnDisable = false } = {}) => {
    try {
      const settings = requireConfig();

      if (!settings.free_samples_enabled) {
        const result = await removeAllGiftedItems({ refreshOnNoMatch: refreshOnDisable });
        // If refreshOnNoChange is true, only refresh if something was actually removed
        if (refreshOnNoChange) {
          result.needsRefresh = result.removed > 0;
        }
        return result;
      }

      const cart = await resolveCart(cartContent);

      const isPriceCondition = settings['free-products__condition_type'] === 'price';
      const threshold = settings['free-products__condition_price'] * 100;
      const conditionCollection = settings['free-products__condition_collection'];

      // Get eligible product IDs from collection (if specified)
      let eligibleProductIds = null;
      if (conditionCollection) {
        eligibleProductIds = await getCollectionProductIds(conditionCollection);
      }

      // Calculate cart total EXCLUDING gifted items and filtering by collection if specified
      const cartTotalWithoutGifts = cart.items.reduce((total, item) => {
        const isGiftedItem = item.properties?._Gifted === true && item.properties?._autoAdded === true;
        if (isGiftedItem) return total;

        // If collection is specified, only count products from that collection
        if (eligibleProductIds && !eligibleProductIds.includes(item.product_id)) {
          return total;
        }

        return total + item.final_line_price;
      }, 0);

      const meetsThreshold = isPriceCondition && cartTotalWithoutGifts > threshold;
      const belowOrEqualThreshold = isPriceCondition && cartTotalWithoutGifts <= threshold;
      const hasGift = checkGiftInCart(cart);

      if (meetsThreshold && !hasGift) {
        const result = await addToCart();
        // If refreshOnNoChange is true, refresh because we added something
        if (refreshOnNoChange) {
          result.needsRefresh = true;
        }
        return result;
      }

      if (belowOrEqualThreshold) {
        const result = await removeAllGiftedItems({ refreshOnNoMatch: refreshOnDisable });
        // If refreshOnNoChange is true, only refresh if something was actually removed
        if (refreshOnNoChange) {
          result.needsRefresh = result.removed > 0;
        }
        return result;
      }

      // No changes needed - only refresh if refreshOnNoChange is false (meaning always refresh)
      return { needsRefresh: !refreshOnNoChange, reason: 'unchanged' };
    } catch (error) {
      console.error('[FreeProduct] Error checking gift condition:', error);
      throw error;
    }
  };

  const HANDLE_DEFAULT_OPTIONS = {
    refreshOnNoChange: true,
    refreshOnDisable: false,
  };

  const handleGiftConditionWithRefresh = async ({
    cartContent,
    options = {},
    suppressRefresh = false,
    refreshHandler,
  } = {}) => {
    const mergedOptions = {
      ...HANDLE_DEFAULT_OPTIONS,
      ...options,
    };

    const { forceRefresh = false, ...checkOptions } = mergedOptions;
    const result = await checkGiftCondition(cartContent, checkOptions);
    const shouldRefresh = forceRefresh || result?.needsRefresh;

    if (shouldRefresh && suppressRefresh !== true) {
      if (typeof refreshHandler === 'function') {
        await refreshHandler(result);
      } else {
        refreshCart();
      }
    }

    if (forceRefresh && result && !result.needsRefresh) {
      result.needsRefresh = true;
    }

    return { result, options: mergedOptions };
  };

  // Aggiungi questa funzione per aggiornare il cart count
  const updateCartCount = (cart) => {
    // Aggiorna tutti i cart-count elements
    const cartCountElements = document.querySelectorAll('cart-count');
    cartCountElements.forEach((element) => {
      if (element.itemCount !== undefined) {
        element.itemCount = cart.item_count;
      }
    });

    // Aggiorna tutti i cart-dot elements per la visibilità e il count interno
    const cartDotElements = document.querySelectorAll('cart-dot');
    cartDotElements.forEach((element) => {
      element.classList.toggle('is-visible', cart.item_count > 0);

      // Aggiorna il numero dentro lo span cart-item-count
      const countSpan = element.querySelector('.cart-item-count');
      if (countSpan) {
        countSpan.textContent = cart.item_count;
      }
    });
  };

  const handleSyncEvent = async (event) => {
    const detail = event.detail ?? {};

    try {
      const { result, options } = await handleGiftConditionWithRefresh({
        cartContent: detail.cart,
        options: detail.options,
        suppressRefresh: detail.suppressRefresh,
        refreshHandler: detail.refreshHandler,
      });

      // Aggiorna il cart count dopo l'operazione
      const finalCart = result?.data || detail.cart || (await fetchCart());
      updateCartCount(finalCart);

      detail.resolve?.(result);

      document.dispatchEvent(
        new CustomEvent('free-product:synced', {
          detail: { cart: detail.cart, result, options },
        }),
      );
    } catch (error) {
      console.error('[FreeProduct] Error syncing gift condition:', error);
      detail.reject?.(error);

      document.dispatchEvent(
        new CustomEvent('free-product:error', {
          detail: { cart: detail.cart, error },
        }),
      );
    }
  };

  document.addEventListener('free-product:sync', handleSyncEvent);

  // Helper centralizzato per dispatchare l'evento sync
  const dispatchSync = (cartContent, options = {}) =>
    new Promise((resolve, reject) => {
      document.dispatchEvent(
        new CustomEvent('free-product:sync', {
          detail: {
            cart: cartContent,
            options,
            resolve,
            reject,
          },
        }),
      );
    });

  // Helper centralizzato con defaults comuni
  const sync = (cartContent, overrides = {}) =>
    dispatchSync(cartContent, {
      refreshOnNoChange: true,
      refreshOnDisable: false,
      ...overrides,
    });

  // Verifica se il modulo è abilitato
  const isEnabled = () => state.themeSettings?.free_samples_enabled !== false;

  const FreeProduct = {
    configure({ themeSettings, cartUrl }) {
      state.themeSettings = themeSettings;
      state.cartUrl = cartUrl;
    },
    // Core functions
    checkGiftCondition,
    removeAllGiftedItems,
    addToCart,
    checkGiftInCart,
    refreshCart,
    handleGiftConditionWithRefresh,
    // Helpers centralizzati
    fetchCart,
    dispatchSync,
    sync,
    isEnabled,
  };

  document.addEventListener('cart:change', (event) => {
    if (event.detail && event.detail.cart) {
      setCachedCart(event.detail.cart);
    } else {
      invalidateCart();
    }
  });

  document.addEventListener('cart:refresh', (event) => {
    invalidateCart();
  });

  // ============================================
  // AUTO-INITIALIZATION AND EVENT LISTENERS
  // ============================================

  /**
   * Remove all auto-added gift items from cart
   * (moved from theme.liquid)
   */
  async function removeAutoAddedGifts() {
    try {
      const response = await fetch('/cart.js', {
        credentials: 'same-origin',
        headers: { Accept: 'application/json' },
      });

      if (!response.ok) return;

      const cart = await response.json();
      const giftItem = cart.items.find(
        (item) => item.properties?._Gifted === true && item.properties?._autoAdded === true,
      );

      if (giftItem) {
        await fetch('/cart/change.js', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: giftItem.key, quantity: 0 }),
        });
        window.location.reload();
      }
    } catch (error) {
      console.error('[FreeProduct] Error removing auto-added gift:', error);
    }
  }

  /**
   * Event Handlers
   */
  let isWaitingForLoadingEnd = false;

  async function onDomReady() {
    if (window.location.pathname !== getCartUrl()) {
      await sync();
    }
  }

  async function handleCartChange(event) {
    if (window.location.pathname !== getCartUrl()) {
      await sync(event.detail.cart);
    }
  }

  async function handleCustomizationAdd(event) {
    if (window.location.pathname !== getCartUrl()) {
      await sync(event.detail.cart);
    }
  }

  function handleLineItemWillChange() {
    isWaitingForLoadingEnd = true;
  }

  async function handleCartPageChange(event) {
    if (!isWaitingForLoadingEnd) return;

    if (window.location.pathname === getCartUrl()) {
      await sync(event.detail.cart);
    }

    isWaitingForLoadingEnd = false;
  }

  /**
   * Register quantity selectors on cart page
   * Handles both quantity change AND free product sync
   */
  let isProcessingQuantityChange = false;

  function registerQuantitySelectors() {
    const selectors = document.querySelectorAll('.quantity-selector__select');

    selectors.forEach((select) => {
      // Store initial value on focus
      select.addEventListener('focus', (event) => {
        event.target.setAttribute('data-previous-value', event.target.value);
      });

      // Handle quantity change
      select.addEventListener('change', async (event) => {
        // Prevent concurrent changes
        if (isProcessingQuantityChange) {
          select.value = select.getAttribute('data-previous-value') || select.value;
          return;
        }

        const previousValue = select.getAttribute('data-previous-value') || select.value;
        const spinner = select.parentElement?.querySelector('.selector__spinner');
        isProcessingQuantityChange = true;

        event.stopImmediatePropagation();

        try {
          const newQuantity = parseInt(select.value, 10);
          const lineKey = select.dataset.lineKey;
          select.setAttribute('data-previous-value', previousValue);

          if (!lineKey) {
            console.warn('[FreeProduct] No line key found');
            return;
          }

          // Show spinner if available
          if (spinner) {
            select.parentElement.setAttribute('aria-busy', 'true');
          }

          // Call /cart/change.js to update quantity
          const response = await fetch('/cart/change.js', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              id: lineKey,
              quantity: newQuantity,
            }),
          });

          if (!response.ok) {
            throw new Error('Error updating quantity: ' + response.statusText);
          }

          const updatedCart = await response.json();

          // Sync free products
          await sync(updatedCart, {
            refreshOnDisable: true,
            forceRefresh: true,
          });

          // Update stored value
          select.setAttribute('data-previous-value', String(newQuantity));
        } catch (error) {
          console.error('[FreeProduct] Quantity change error:', error);
          // Rollback on error
          select.value = previousValue || '1';
          select.setAttribute('data-previous-value', select.value);
        } finally {
          // Hide spinner
          if (spinner) {
            select.parentElement.setAttribute('aria-busy', 'false');
          }

          isProcessingQuantityChange = false;
        }
      });
    });
  }

  /**
   * Register all event listeners
   */
  function registerAllEventListeners() {
    const cartUrl = getCartUrl();

    // 1. Initial check on DOM ready
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', onDomReady);
    } else {
      onDomReady();
    }

    // 2. Cart change
    document.addEventListener('cart:change', handleCartChange);

    // 3. Customization product added
    document.addEventListener('cart:add-customization-product', handleCustomizationAdd);

    // 4. Line item changes on cart page
    document.addEventListener('line-item:will-change', handleLineItemWillChange);
    document.addEventListener('cart:page-change', handleCartPageChange);

    // 5. Quantity selectors (only on cart page)
    if (window.location.pathname === cartUrl) {
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', registerQuantitySelectors);
      } else {
        registerQuantitySelectors();
      }
    }
  }

  /**
   * Auto-configure from script tag data attributes
   */
  function autoConfigureFromScriptTag() {
    const scriptTag = document.currentScript || document.querySelector('script[src*="free-product"]');

    if (!scriptTag) {
      console.warn('[FreeProduct] Could not find script tag');
      return false;
    }

    try {
      const themeSettings = JSON.parse(scriptTag.dataset.themeSettings || '{}');
      const cartUrl = scriptTag.dataset.cartUrl || '/cart';

      FreeProduct.configure({ themeSettings, cartUrl });
      return true;
    } catch (error) {
      console.error('[FreeProduct] Error parsing config:', error);
      return false;
    }
  }

  /**
   * Auto-initialization
   */
  (function autoInit() {
    // Try to auto-configure from script tag
    if (!autoConfigureFromScriptTag()) {
      console.warn('[FreeProduct] Auto-configuration failed, waiting for manual configure()');
      // Expose to window for manual configuration
      window.FreeProduct = FreeProduct;
      document.dispatchEvent(new CustomEvent('free-product:ready', { detail: FreeProduct }));
      return;
    }

    const settings = state.themeSettings;

    // If disabled, remove gifts and exit
    if (settings?.free_samples_enabled === false) {
      window.free_samples_enabled = false;
      removeAutoAddedGifts();
      // Still expose FreeProduct for backward compatibility
      window.FreeProduct = FreeProduct;
      document.dispatchEvent(new CustomEvent('free-product:ready', { detail: FreeProduct }));
      return;
    }

    // Register all event listeners
    registerAllEventListeners();

    // Expose to window
    window.FreeProduct = FreeProduct;

    // Dispatch ready event
    document.dispatchEvent(new CustomEvent('free-product:ready', { detail: FreeProduct }));
  })();
})();
